DROP TABLE IF EXISTS `wf_node_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_node_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `model_key` varchar(64) NOT NULL COMMENT '流程定义key',
  `node_key` varchar(64) NOT NULL COMMENT '节点ID(BPMN userTask id)',
  `node_name` varchar(200) NOT NULL COMMENT '节点名称',
  `assign_type` varchar(30) NOT NULL DEFAULT 'DEPT_LEADER' COMMENT '审批人类型:USER指定人/ROLE角色/POST岗位/DEPT_LEADER部门负责人/DEPT_LEADER_UP逐级上级/INITIATOR发起人/SHARE_POOL共享池/EXPRESSION表达式',
  `assign_value` varchar(500) DEFAULT NULL COMMENT '审批人取值,多个逗号分隔(用户ID/角色ID/岗位ID/表达式)',
  `handling_mode` varchar(20) NOT NULL DEFAULT 'AUTO' COMMENT '取人方式:AUTO自动指派/PICK上一环节指定/POOL任务池领取',
  `up_level` int NOT NULL DEFAULT '1' COMMENT '逐级上级时向上层数',
  `multi_type` varchar(20) NOT NULL DEFAULT 'ANY' COMMENT '多人审批规则:ANY任一通过/ALL会签全部通过/SEQ顺序审批/VOTE票签',
  `vote_ratio` int NOT NULL DEFAULT '50' COMMENT '票签通过比例(%)',
  `vote_mode` varchar(16) DEFAULT NULL COMMENT 'G2票签取值方式:RATIO比例(默认)/COUNT确定票数',
  `vote_value` int DEFAULT NULL COMMENT 'G2票签阈值:vote_mode=RATIO时为百分比1~100;COUNT时为所需票数',
  `vote_basis` varchar(16) DEFAULT NULL COMMENT 'G2票签分母口径:BY_PERSON参与人总数(应到,默认)/BY_VOTE已投票数(实到)',
  `vote_fallback` varchar(16) DEFAULT NULL COMMENT 'G2不达票兜底:REJECT驳回收尾(默认)/PASS放行流程继续',
  `allow_transfer` tinyint NOT NULL DEFAULT '1' COMMENT '允许转办:0否 1是',
  `allow_addsign` tinyint NOT NULL DEFAULT '0' COMMENT '允许加签:0否 1是',
  `empty_strategy` varchar(20) NOT NULL DEFAULT 'ERROR' COMMENT '找不到审批人时:ADMIN转管理员/SKIP自动跳过/ERROR报错阻断',
  `auto_pass_self` tinyint NOT NULL DEFAULT '0' COMMENT '审批人=发起人时自动通过:0否 1是',
  `timeout_hours` int DEFAULT NULL COMMENT '超时小时数,空表示不限',
  `timeout_action` varchar(20) DEFAULT 'NOTIFY' COMMENT '超时动作:NOTIFY催办/AUTO_PASS自动通过/AUTO_TRANSFER自动转办',
  `form_perm` text COMMENT '本节点字段权限JSON:{"field":"R/W/H"}',
  `cc_users` varchar(500) DEFAULT NULL COMMENT '本节点办结后抄送的用户ID,逗号分隔（与运行时入参 ccUserIds 取并集）',
  `cc_roles` varchar(500) DEFAULT NULL COMMENT '本节点办结后抄送的角色编码,逗号分隔（运行期展开为在职成员）',
  `first_node_auto_pass` tinyint(1) DEFAULT NULL COMMENT 'F10首节点提单即完成:1是/0否/NULL未配置(回退旧判据:节点名含提交)',
  `sort` int NOT NULL DEFAULT '0',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  `reject_scope` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT 'G2驳回范围:NONE不允许指定节点驳回(默认)/PREV_ONE只可退回紧邻上一节点/ANY_DONE可退回任一已完成节点',
  `resubmit_jump_back` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'G2重新提交跳回本节点:1本节点驳回后记录实例变量rejectOriginNode,重新提交时跳回本节点;0关闭',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_model_node` (`tenant_id`,`model_key`,`node_key`),
  KEY `idx_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程节点审批人配置';
/*!40101 SET character_set_client = @saved_cs_client */;

